WITH agg AS ( SELECT d.d_fy_year AS fiscal_year, i.i_category AS category, SUM(cs.cs_net_profit) AS total_sales_profit, SUM(cr.cr_net_loss) AS total_return_loss, SUM(cr.cr_fee) AS total_return_fees, SUM(cs.cs_net_profit) - SUM(cr.cr_net_loss) - SUM(cr.cr_fee) AS net_profit_after_returns, (SUM(cr.cr_return_quantity) * 1.0) / NULLIF(SUM(cs.cs_quantity), 0) AS return_rate, COUNT(DISTINCT cs.cs_order_number) AS orders_count, COUNT(DISTINCT cr.cr_order_number) AS returns_count FROM catalog_sales cs JOIN catalog_returns cr ON cs.cs_order_number = cr.cr_order_number AND cs.cs_item_sk = cr.cr_item_sk JOIN date_dim d ON cs.cs_sold_date_sk = d.d_date_sk JOIN item i ON cs.cs_item_sk = i.i_item_sk JOIN reason r ON cr.cr_reason_sk = r.r_reason_sk WHERE d.d_fy_year BETWEEN 1999 AND 2002 AND cr.cr_warehouse_sk IN (1, 12, 16) AND r.r_reason_desc LIKE '%defective%' GROUP BY d.d_fy_year, i.i_category HAVING SUM(cs.cs_net_profit) > 10000 ) SELECT fiscal_year, category, total_sales_profit, total_return_loss, total_return_fees, net_profit_after_returns, return_rate, orders_count, returns_count, RANK() OVER (PARTITION BY fiscal_year ORDER BY net_profit_after_returns DESC) AS profit_rank FROM agg ORDER BY net_profit_after_returns DESC LIMIT 50
